// The visual "Looks" the app can wear. `classic` is the original appearance (no data-look attribute, no extra CSS applies).
// A look = an entry here + CSS scoped under :root[data-look="<id>"]. Drop one by deleting its entry and folder; anyone who
// had it selected falls back to Classic (see resolveLook). Shared pattern art lives in shared/patterns.css, generated by
// tools/gen_look_patterns.py.
import './shared/patterns.css'
import './shared/motifs.css'
import './patterns/look.css'
import './motifs/look.css'
import './signatures/look.css'
import './output-art/look.css'

export const LOOKS = [
  { id: 'classic',  label: 'Classic',  blurb: 'The original Videobeaux Television look.' },
  { id: 'patterns', label: 'Patterns', blurb: 'Memphis-style patterns in every module header and in the sidebar — each family of effects wears its own.' },
  { id: 'motifs', label: 'Motifs', blurb: 'Header patterns that depict what each module does — one pattern per mechanic, never shared across categories.' },
  { id: 'signatures', label: 'Signatures', blurb: 'Patterns plus a cartoon glyph per module, a recognisable strip when collapsed, and Group-by-family in the sidebar.' },
  { id: 'output-art', label: 'Output art', blurb: 'As Signatures, but the picture on a collapsed module — and a hover preview in the sidebar — is cropped from what that module really produces.' }
]

export function resolveLook(id) {
  return LOOKS.some(l => l.id === id) ? id : 'classic'
}
